on conflict (collection,id) do nothing;

-- Everything that is not in the clothing catalogue leaves the storefront.
update public.admin_data
   set document = document || jsonb_build_object('status','archived','updatedAt',now(),
         'revision',coalesce((document->>'revision')::int,0)+1),
       updated_at = now()
 where collection = 'products'
   and id not in ('men-oversized-tee','men-waffle-polo','men-oxford-shirt','men-linen-shirt','men-slim-jeans','men-chinos','men-graphic-tee','women-wrap-dress','women-ribbed-top','women-mom-jeans','women-pleated-skirt','women-puff-blouse','kids-party-frock','kids-tee-shorts-set','kids-zip-hoodie','kids-daura-suruwal','ethnic-daura-suruwal','ethnic-dhaka-topi','ethnic-silk-saree','ethnic-cotton-kurti','ethnic-kurta-pajama','ethnic-lehenga','winter-puffer-jacket','winter-fleece-hoodie','winter-pashmina-shawl','winter-cable-sweater','winter-women-cardigan','winter-pompom-beanie','active-running-shorts','active-yoga-leggings','active-sports-top','active-track-jacket','active-jogger-pants','acc-tactical-belt','acc-uv-face-shield','acc-baseball-cap','offer-basic-tee-pack','offer-ankle-socks','offer-leggings-pair','offer-check-muffler','offer-kids-tee-pack','offer-sun-visor','offer-boxer-briefs','offer-summer-balaclava','choice-denim-jacket','choice-floral-kurta-set','choice-kids-jeans','choice-dhaka-jacket','rec-printed-scarf','rec-thermal-top','rec-cotton-shorts','rec-kids-beanie')
   and document->>'status' is distinct from 'archived';
update public.products set active = false where id not in ('men-oversized-tee','men-waffle-polo','men-oxford-shirt','men-linen-shirt','men-slim-jeans','men-chinos','men-graphic-tee','women-wrap-dress','women-ribbed-top','women-mom-jeans','women-pleated-skirt','women-puff-blouse','kids-party-frock','kids-tee-shorts-set','kids-zip-hoodie','kids-daura-suruwal','ethnic-daura-suruwal','ethnic-dhaka-topi','ethnic-silk-saree','ethnic-cotton-kurti','ethnic-kurta-pajama','ethnic-lehenga','winter-puffer-jacket','winter-fleece-hoodie','winter-pashmina-shawl','winter-cable-sweater','winter-women-cardigan','winter-pompom-beanie','active-running-shorts','active-yoga-leggings','active-sports-top','active-track-jacket','active-jogger-pants','acc-tactical-belt','acc-uv-face-shield','acc-baseball-cap','offer-basic-tee-pack','offer-ankle-socks','offer-leggings-pair','offer-check-muffler','offer-kids-tee-pack','offer-sun-visor','offer-boxer-briefs','offer-summer-balaclava','choice-denim-jacket','choice-floral-kurta-set','choice-kids-jeans','choice-dhaka-jacket','rec-printed-scarf','rec-thermal-top','rec-cotton-shorts','rec-kids-beanie');

-- Old departments are switched off; their products are archived above.
update public.admin_data
   set document = document || jsonb_build_object('enabled',false,'updatedAt',now()), updated_at = now()
 where collection = 'categories'
   and id not in ('cat_men','cat_women','cat_kids','cat_ethnic-wear','cat_winter-wear','cat_activewear','cat_accessories')
   and coalesce((document->>'enabled')::boolean,true);

-- Wording that still reads like a general store.
update public.app_config set published = jsonb_set(published,'{branding,tagline}','"Fashion for every season, delivered."')
 where published#>>'{branding,tagline}' = 'Everyday fancy goods, delivered.';
update public.app_config set published = jsonb_set(published,'{header,searchPlaceholder}','"Search shirts, kurtis, jackets…"')
 where published#>>'{header,searchPlaceholder}' = 'Search for products';
update public.app_config set published = jsonb_set(published,'{text,homeHeading}','"New season styles for the whole family"')
 where published#>>'{text,homeHeading}' = 'Shop with Gulmeli Fancy Stores';

commit;
